"""End-to-end tests of scripts/build_codex_agents.py against a temporary home."""

import subprocess
import sys
from pathlib import Path

import pytest

SCRIPT = Path(__file__).resolve().parents[1] / "scripts/build_codex_agents.py"
CORE = "# Shared instructions\n\nThe core.\n"
LAYER = "# Personal layer\n\nThe layer.\n"
HEADER = (
    "<!-- Generated by build_codex_agents.py from ~/.claude/CLAUDE.md and ~/.claude/rules/personal.md. "
    "Do not edit it by hand: edit those two files, then rerun build_codex_agents.py. -->"
)


@pytest.fixture
def home(tmp_path: Path) -> Path:
    """A home with the core and the personal layer where Claude Code loads them, and no codex instructions yet."""
    home = tmp_path / "home"
    (home / ".claude/rules").mkdir(parents=True)
    (home / ".codex").mkdir()
    (home / ".claude/CLAUDE.md").write_text(CORE)
    (home / ".claude/rules/personal.md").write_text(LAYER)
    return home


def build(home: Path, *args: str) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        [sys.executable, str(SCRIPT), *(args or [str(home / ".claude/rules/personal.md")])],
        env={"HOME": str(home), "PATH": "/usr/bin:/bin"},
        capture_output=True,
        text=True,
        check=False,
    )


class TestBuildCodexAgents:
    def test_replaces_the_old_symlink_with_the_core_then_the_layer_under_a_header(self, home: Path) -> None:
        out = home / ".codex/AGENTS.md"
        out.symlink_to(home / ".claude/CLAUDE.md")

        result = build(home)

        assert result.returncode == 0, result.stderr
        assert result.stderr == f"wrote {out}\n"
        assert not out.is_symlink()
        assert out.read_text() == f"{HEADER}\n\n{CORE.rstrip()}\n\n{LAYER}"
        assert (home / ".claude/CLAUDE.md").read_text() == CORE
        assert out.stat().st_mode & 0o777 == 0o644

    def test_rewrites_only_when_a_source_changed(self, home: Path) -> None:
        out = home / ".codex/AGENTS.md"
        assert build(home).returncode == 0
        first_inode = out.stat().st_ino

        rerun = build(home)

        assert rerun.stderr == f"unchanged: {out}\n"
        assert out.stat().st_ino == first_inode
        (home / ".claude/rules/personal.md").write_text(LAYER + "\nA new rule.\n")
        assert build(home).stderr == f"wrote {out}\n"
        assert out.read_text().endswith("A new rule.\n")

    def test_never_overwrites_a_hand_written_file(self, home: Path) -> None:
        out = home / ".codex/AGENTS.md"
        out.write_text("my own codex rules\n")

        result = build(home)

        assert result.returncode != 0
        assert "is a regular file this script did not write" in result.stderr
        assert out.read_text() == "my own codex rules\n"

    def test_a_missing_layer_stops_before_any_write(self, home: Path) -> None:
        layer = home / ".claude/rules/personal.md"
        layer.unlink()

        result = build(home)

        assert result.returncode != 0
        assert f"{layer} is missing" in result.stderr
        assert not (home / ".codex/AGENTS.md").exists()

    def test_names_sources_in_home_form_through_either_spelling_of_a_symlinked_home(
        self, home: Path, tmp_path: Path
    ) -> None:
        alias = tmp_path / "home-alias"
        alias.symlink_to(home, target_is_directory=True)
        outside_core = tmp_path / "elsewhere/core.md"
        outside_core.parent.mkdir()
        outside_core.write_text(CORE)

        result = build(alias, "--core", str(outside_core), str(home / ".claude/rules/personal.md"))

        assert result.returncode == 0, result.stderr
        header = (home / ".codex/AGENTS.md").read_text().split("\n\n", 1)[0]
        assert f"from {outside_core} and ~/.claude/rules/personal.md." in header
